<div x-data="complaintIndex()" x-init="init()" x-cloak><div class="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="text-sm text-slate-600">Pantau laporan masyarakat</p><h2 class="mt-1 text-2xl font-semibold tracking-tight text-navy-900">Daftar Aduan</h2></div><a href="{{ route('complaints.create') }}" class="action-button-primary">+ Kirim aduan</a></div><section class="rounded-2xl border border-border bg-white p-4 shadow-sm"><div class="grid gap-3 md:grid-cols-4"><input x-model="search" class="field-input" placeholder="Cari kode, alamat, deskripsi"><select x-model="filters.type" class="field-input"><option value="">Semua aset</option><option value="lpju">LPJU</option><option value="rambu">Rambu</option></select><select x-model="filters.status" class="field-input"><option value="">Semua status</option><option value="baru">Baru</option><option value="diproses">Diproses</option><option value="selesai">Selesai</option></select><input x-model="filters.from" type="date" class="field-input" aria-label="Dari tanggal"></div></section><div x-show="error" class="mt-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700" x-text="error"></div><section class="mt-5 overflow-hidden rounded-2xl border border-border bg-white shadow-sm"><div class="border-b border-border px-5 py-4"><h3 class="font-semibold text-navy-900">Laporan masuk</h3><p class="mt-1 text-xs text-slate-500" x-text="`${filtered.length} aduan ditampilkan`"></p></div><div class="overflow-x-auto"><table class="w-full min-w-[800px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-5 py-3">Kode</th><th class="px-5 py-3">Aset</th><th class="px-5 py-3">Lokasi</th><th class="px-5 py-3">Tanggal</th><th class="px-5 py-3">Status</th><th class="px-5 py-3 text-right">Aksi</th></tr></thead><tbody class="divide-y divide-border"><template x-for="item in filtered" :key="item.id"><tr><td class="px-5 py-4 font-semibold text-navy-900" x-text="code(item)"></td><td class="px-5 py-4 text-slate-600" x-text="type(item)"></td><td class="px-5 py-4 text-slate-600" x-text="item.alamat_kejadian || item.aset?.alamat || '-' "></td><td class="px-5 py-4 text-slate-600" x-text="item.tanggal_aduan || '-' "></td><td class="px-5 py-4"><span class="inline-flex rounded-full px-2.5 py-1 text-xs font-medium" :class="statusClass(item.status_aduan)" x-text="item.status_aduan"></span></td><td class="px-5 py-4 text-right"><a :href="`{{ url("/complaints") }}/${item.id}`" class="action-link">Detail</a></td></tr></template></tbody></table></div><p x-show="!loading && !filtered.length" class="px-5 py-16 text-center text-sm text-slate-500">Belum ada aduan yang sesuai.</p></section></div>
<script>const complaintApiBase = @json(url("/api"));
function complaintIndex(){return{items:[],loading:true,error:'',search:'',filters:{type:'',status:'',from:''},async init(){try{const r=await window.axios.get(`${complaintApiBase}/aduan`);this.items=r.data?.data||r.data||[]}catch(e){this.error=e.response?.data?.message||'Gagal memuat aduan.'}finally{this.loading=false}},get filtered(){const q=this.search.toLowerCase().trim();return this.items.filter(x=>(!q||[this.code(x),x.alamat_kejadian,x.deskripsi,x.aset?.alamat].filter(Boolean).join(' ').toLowerCase().includes(q))&&(!this.filters.type||this.type(x).toLowerCase()===this.filters.type)&&(!this.filters.status||x.status_aduan===this.filters.status)&&(!this.filters.from||String(x.tanggal_aduan)>=this.filters.from))},code(x){return`ADUAN-${String(x.id).padStart(6,'0')}`},type(x){return String(x.aset_type||'').toLowerCase().includes('rambu')?'Rambu':'LPJU'},statusClass(status){return status==='selesai'?'bg-teal-100 text-teal-800':status==='diproses'?'bg-yellow-100 text-yellow-800':status==='baru'?'bg-red-100 text-red-800':'bg-slate-100 text-slate-700'}}}</script>
@endsection
